# UNA IP, UN CONTRATO VIGENTE, POR EMPRESA  --  27/11/2026.
#
# La columna `ip` repite `datos["ip_elegida"]` para que la base pueda negarse a
# guardar dos contratos vigentes de la empresa con la misma direccion (ver
# `ContratoDeServicio.ip`). El paso del medio copia la IP de los contratos que
# ya existen ANTES de crear la regla: si en la base hubiera dos vigentes con la
# misma, la conserva el mas antiguo y el otro queda sin ella en la columna (sus
# datos firmados no se tocan). Asi la regla se crea siempre y el despliegue no
# se cae por un dato viejo; el aviso dice cuantos hay que revisar, sin nombrar
# ninguna IP ni ningun cliente.

from django.conf import settings
from django.db import migrations, models


def copiar_las_ip(apps, schema_editor):
    Contrato = apps.get_model("campo", "ContratoDeServicio")
    vistas: set[tuple] = set()
    repetidos = 0
    for c in (Contrato.objects.order_by("firmado_en", "created_at", "id")
              .only("id", "org_id", "estado", "datos").iterator()):
        ip = str((c.datos or {}).get("ip_elegida") or "").strip()[:15]
        if not ip:
            continue
        if c.estado != "anulado":
            clave = (c.org_id, ip)
            if clave in vistas:
                repetidos += 1
                continue
            vistas.add(clave)
        Contrato.objects.filter(pk=c.pk).update(ip=ip)
    if repetidos:
        print(f"\n  [campo 0067] {repetidos} contrato(s) vigente(s) comparten la IP con "
              f"uno anterior de su empresa: quedaron sin la columna `ip`. Revisarlos.")


